import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:get/get.dart';

import '../../firebase_options.dart';

/// Initialises Firebase with the options generated by `flutterfire configure`
/// (project `habesha-baby-names`).
///
/// If initialisation fails (unsupported platform such as Linux, no network
/// on a first cold start of a misconfigured build, …) the app keeps working
/// offline from the bundled seed with [isAvailable] = false.
class FirebaseService extends GetxService {
  bool _available = false;

  bool get isAvailable => _available;

  Future<FirebaseService> init() async {
    try {
      await Firebase.initializeApp(
        options: DefaultFirebaseOptions.currentPlatform,
      );
      _available = true;
    } catch (error) {
      debugPrint('Firebase unavailable — running offline only. ($error)');
    }
    return this;
  }
}
